"use strict";
// World Map Outlines for Phantom Blade Zero: a PBZModLoader mod (ProjectPBZ/PBZModLoader/mods/phantombladezero_worldmapoutlines/).
//
// The world map shows a soft outline around every region you have discovered, all the time. The game's map script
// (UI/Widget/Map.js) exports MapInterface, the mixin of the map widget WB_MapNew_C; the mod wraps its
// UpdateBigMapGadgetIcon, which the game calls every frame while the world map shows. There, at most every REFRESH_MS,
// it reads the discovered regions by the map's own rule (BellManager.ActivateBellIDs, then each bell's
// BellManager.GetBellData(id).MapID) and shows one outline Image per discovered region on the map's BigMapGadget canvas:
// anchored to the region's box (REGIONS, shares of the canvas, so it follows pan and zoom), below the game's fog and
// markers (ZOrder -1), never in the way of the cursor (HitTestInvisible). The outlines are inside this file (IMAGES,
// PNG as base64) and become textures in memory (KismetRenderingLibrary.ImportBufferAsTexture2D): no image files.
// stop() removes every outline and the wrap. Nothing is written into the save.
//
// Ported from the author's earlier UE4SS mod "TracedLands" 0.1.2 (a Lua script that searched the map widgets every
// 250 ms, and the same eight images as loose PNG files). The region boxes and the images are that mod's.
// 1.1: the wrapper reaches the copy that runs now through globalThis (FRAME_KEY), so the outlines survive Alt+F5.
// 1.2: the same code as 1.1; a release that tests how mod managers find an update and its release notes.
//
// PBZModLoader loads this file after the game's MainStart, through the game's module system: require("ue"),
// require("puerts") and require("Library/TsHelper") are the game's modules. Before a reload (Alt+F5) it awaits stop().
// Settings: phantombladezero_worldmapoutlines.txt next to this file (__dirname), "Key=Value" lines (; or # starts a
// comment, the first line of a key wins), read at most every SETTINGS_MS while the world map shows, and written with
// the defaults when missing. With Mods Menu (0.9.0 or later) running, the mod adds its page there and reads the file that
// page saves instead (a page cannot save anywhere else).
const UE = require("ue");
const puerts = require("puerts");

const MOD_NAME = "World Map Outlines";
const MOD_ID = "phantombladezero_worldmapoutlines"; // the mod folder's name and Mods Menu's page id
const MOD_VERSION = "1.2";
const SETTINGS_MS = 2000;
const REFRESH_MS = 250; // the discovered regions, read again while the world map shows
const SETTINGS_FILE = MOD_ID + ".txt";
const VIS = UE.ESlateVisibility;
// Every setting with its default; the shipped settings file holds exactly this text (tests/test_mod.js checks it).
const DEFAULT_TEXT = ["; " + MOD_NAME + " settings. Change a value and save; the world map picks it up within 2 seconds.",
    "; Enable: On, or Off (the game's own world map).",
    "; Opacity: 0.1 to 1, how strong the outlines show (1 = as drawn).",
    "Enable=On", "Opacity=1", ""].join("\r\n");
// The eight regions: the map's MapID (lower case) and its box as shares of the world map canvas (the source's table).
const REGIONS = [
    { id: "xigu", min: [0.45240761478163494, 0.724609375], max: [0.5856662933930571, 0.927734375] },
    { id: "fujizhilin", min: [0.44400895856662936, 0.609375], max: [0.6394176931690929, 0.755859375] },
    { id: "lujiacun", min: [0.48040313549832026, 0.4921875], max: [0.6573348264277715, 0.662109375] },
    { id: "zhengdaodaying", min: [0.6416573348264277, 0.35546875], max: [0.8633818589025756, 0.591796875] },
    { id: "dengdingshandao", min: [0.4748040313549832, 0.181640625], max: [0.5996640537513998, 0.380859375] },
    { id: "duanhunya", min: [0.3012318029115342, 0.119140625], max: [0.46024636058230683, 0.4453125] },
    { id: "meiguhu", min: [0.374020156774916, 0.4423828125], max: [0.6002239641657335, 0.587890625] },
    { id: "pangzhen", min: [0.2116461366181411, 0.431640625], max: [0.406494960806271, 0.646484375] },
];
// IMAGES: begin. Written by scripts/embed_images.py from assets/<id>.png; do not edit by hand.
const IMAGES = {
    "xigu": "",
    "fujizhilin": "",
    "lujiacun": "",
    "zhengdaodaying": "",
    "dengdingshandao": "",
    "duanhunya": "",
    "meiguhu": "",
    "pangzhen": "",
};
// IMAGES: end

// The settings and the map widgets the mod has drawn on.
const run = { stopped: false, path: undefined, readAt: -Infinity, made: false, said: new Set(),
    settings: { enable: true, opacity: 1 } };
const hosts = new Set();
const textures = new Map(); // region id -> its texture this session
const bellRegions = new Map(); // bell id -> its map's region id
const wrapped = []; // { proto, name, original, wrapper }

// The Mods Menu page (optional): one row per setting, the same keys and defaults as DEFAULT_TEXT.
const page = () => ({ id: MOD_ID, title: MOD_NAME, version: MOD_VERSION, file: SETTINGS_FILE, store: "saved",
    description: "The world map shows a soft outline around every region you have discovered, all the time.",
    settings: [
        { key: "Enable", type: "toggle", label: "Enable", default: true, help: "Off: the game's own world map." },
        { key: "Opacity", type: "number", label: "Opacity", min: 0.1, max: 1, step: 0.05, default: 1,
            help: "How strong the outlines show. 1 is as drawn." },
    ],
    onChange: () => { run.readAt = -Infinity; } }); // read again at the next map frame
// PBZModLoader starts its mods after Mods Menu's, so a running Mods Menu has its registry object here by now. Without it
// nothing is pushed: an array left for a Mods Menu that starts later would give a page that saves another file.
const menu = { on: false };
{
    const mm = globalThis.PBZModsMenu;
    if (mm && typeof mm === "object" && !Array.isArray(mm) && typeof mm.push === "function"
        && typeof mm.settingsPath === "function" && mm.api && typeof mm.api.has === "function"
        && mm.api.has("settingsPath") && mm.api.has("store.saved")) {
        try {
            mm.push(page());
            menu.on = typeof mm.settingsPath(MOD_ID) === "string";
        }
        catch (e) {
            console.warn(`[${MOD_NAME}] no Mods Menu page: ${e}`);
        }
    }
}

const note = (message) => console.log(`[PBZMOD] [${MOD_NAME}] ${message}`);
function warnOnce(message) {
    if (run.said.has(message))
        return;
    run.said.add(message);
    console.warn(`[${MOD_NAME}] ${message}`);
}
// Puerts throws "passing a invalid object" for a wrapper of an object the game has freed: that is "not valid".
const valid = (o) => {
    if (!o)
        return false;
    try {
        return UE.KismetSystemLibrary.IsValid(o);
    }
    catch (e) {
        return false;
    }
};

// ---- Settings ------------------------------------------------------------------------------------------------------

// The settings file: the one Mods Menu's page saves, else the one next to this main.js.
function settingsPath() {
    if (menu.on) {
        const path = globalThis.PBZModsMenu.settingsPath(MOD_ID);
        if (typeof path === "string" && path)
            return path;
    }
    return UE.KismetSystemLibrary.ConvertToAbsolutePath(String(__dirname).replace(/[\\/]+$/, "") + "/" + SETTINGS_FILE);
}
// The value of `key` in the settings text, in lower case ("" when the key is missing).
function readKey(text, key) {
    const re = new RegExp("^[ \\t]*" + key + "[ \\t]*=[ \\t]*([^;#\\r\\n]*?)[ \\t]*(?:[;#][^\\r\\n]*)?$", "i");
    for (const line of text.split(/\r?\n/)) {
        const m = re.exec(line);
        if (m)
            return m[1].toLowerCase();
    }
    return "";
}
// Reads the settings file at most every SETTINGS_MS. A file that cannot be read keeps the last settings.
function readSettings() {
    if (Math.abs(Date.now() - run.readAt) < SETTINGS_MS)
        return;
    run.readAt = Date.now();
    try {
        run.path = run.path || settingsPath();
        let text = "";
        if (UE.BlueprintPathsLibrary.FileExists(run.path)) { // check first: EasyCsv logs an error for a missing file
            const out = puerts.$ref("");
            if (!UE.EasyCsv.LoadStringFromLocalFile(run.path, out))
                return; // locked mid-save, or 10 characters or fewer: keep the last settings
            text = String(puerts.$unref(out)).replace(/^﻿/, "");
        }
        else if (!run.made) {
            run.made = true; // once a session, and never over an existing file
            UE.EasyCsv.SaveStringToFileWithFullPath(DEFAULT_TEXT, run.path);
        }
        const opacity = parseFloat(readKey(text, "Opacity").replace(",", "."));
        run.settings = { enable: !["off", "0", "no", "false"].includes(readKey(text, "Enable")),
            opacity: Number.isFinite(opacity) ? Math.min(1, Math.max(0.1, opacity)) : 1 };
    }
    catch (e) {
        warnOnce(`settings not read: ${e}`);
    }
}

// ---- The outlines --------------------------------------------------------------------------------------------------

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
// base64 -> bytes (the game's script engine has no atob)
function decode(text) {
    const out = [];
    let bits = 0, value = 0;
    for (const c of text) {
        const v = B64.indexOf(c);
        if (v < 0)
            continue; // "=" padding and line breaks
        value = (value << 6) | v;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            out.push((value >> bits) & 0xff);
        }
    }
    return out;
}
// The region's outline as a texture made in memory from IMAGES; made once a session (again if the game freed it).
function texture(host, id) {
    let tex = textures.get(id);
    if (valid(tex))
        return tex;
    if (!IMAGES[id])
        throw new Error(`no image for ${id}`);
    const buffer = UE.NewArray(UE.BuiltinByte);
    for (const byte of decode(IMAGES[id]))
        buffer.Add(byte);
    tex = UE.KismetRenderingLibrary.ImportBufferAsTexture2D(host, buffer);
    if (!valid(tex))
        throw new Error(`the ${id} outline did not become a texture`);
    textures.set(id, tex);
    return tex;
}
// The regions discovered by the map's own rule: a region of a bell the player has activated.
function discovered(host) {
    const found = new Set();
    const manager = UE.SubsystemBlueprintLibrary.GetWorldSubsystem(host, UE.BellManager.StaticClass());
    if (!valid(manager))
        return found;
    const ids = manager.ActivateBellIDs;
    for (let i = 0; ids && i < ids.Num(); i++) {
        const bell = String(ids.Get(i)); // copied before the next call, as the source did
        if (!bell || bell.toLowerCase() === "none")
            continue;
        let region = bellRegions.get(bell);
        if (region === undefined) {
            const data = UE.BellManager.GetBellData(bell);
            region = data ? String(data.MapID || "").toLowerCase() : "";
            if (region && region !== "none")
                bellRegions.set(bell, region);
        }
        if (region && region !== "none")
            found.add(region);
    }
    return found;
}
function makeOutline(host, canvas, region) {
    const image = UE.NewObject(UE.Image.StaticClass(), host.WidgetTree);
    if (!image)
        throw new Error("no Image for the " + region.id + " outline");
    try {
        image.SetVisibility(VIS.Collapsed);
        image.SetBrushFromTexture(texture(host, region.id), false);
        const slot = canvas.AddChildToCanvas(image);
        slot.SetAutoSize(false);
        const anchors = new UE.Anchors();
        anchors.Minimum = new UE.Vector2D(region.min[0], region.min[1]);
        anchors.Maximum = new UE.Vector2D(region.max[0], region.max[1]);
        slot.SetAnchors(anchors); // the canvas's own share, so the outline follows pan and zoom
        slot.SetOffsets(new UE.Margin(0, 0, 0, 0));
        slot.SetZOrder(-1); // below the game's fog and markers
    }
    catch (e) {
        image.RemoveFromParent();
        throw e;
    }
    return image;
}
function removeOutlines(host) {
    const state = host.__wmo;
    for (const image of Object.values(state ? state.images : {}))
        if (valid(image))
            image.RemoveFromParent();
    host.__wmo = undefined;
    hosts.delete(host);
}
// One world map frame (from the wrapped UpdateBigMapGadgetIcon).
function update(host) {
    readSettings();
    if (!run.settings.enable) {
        if (host.__wmo)
            removeOutlines(host);
        return;
    }
    const canvas = host.BigMapGadget;
    if (!valid(canvas) || !valid(host.WidgetTree))
        return;
    let state = host.__wmo;
    if (state && state.canvas !== canvas) { // the game built its canvas anew
        removeOutlines(host);
        state = undefined;
    }
    if (!state) {
        state = host.__wmo = { canvas, images: {}, failed: {}, at: -Infinity, opacity: undefined };
        hosts.add(host);
    }
    if (Math.abs(Date.now() - state.at) < REFRESH_MS)
        return;
    state.at = Date.now();
    const found = discovered(host);
    for (const region of REGIONS) {
        const show = found.has(region.id);
        let image = state.images[region.id];
        if (show && !valid(image) && !state.failed[region.id]) {
            try {
                image = state.images[region.id] = makeOutline(host, canvas, region);
            }
            catch (e) {
                state.failed[region.id] = true;
                warnOnce(`${region.id}: ${e}`);
                continue;
            }
        }
        if (!valid(image))
            continue;
        const visibility = show ? VIS.HitTestInvisible : VIS.Collapsed;
        if (image.GetVisibility() !== visibility)
            image.SetVisibility(visibility);
        if (image.GetRenderOpacity() !== run.settings.opacity)
            image.SetRenderOpacity(run.settings.opacity);
    }
    const shown = REGIONS.filter((r) => found.has(r.id)).length;
    if (shown !== state.shown) {
        state.shown = shown;
        note(`world map: ${shown} of ${REGIONS.length} regions outlined`);
    }
}

// ---- Start and stop ------------------------------------------------------------------------------------------------

// 1.1: the game can keep calling the function it took when it mixed the map class, so after Alt+F5 the map went on
// calling the old copy's wrapper (stopped), and the new copy never drew (the first game test, 2026-11-14). So no wrapper
// belongs to one copy: every wrapper calls the copy that runs now through globalThis[FRAME_KEY], which start sets and
// stop() clears. Whichever wrapper the game kept reaches the current copy, and nothing once the mod is gone.
const FRAME_KEY = "__worldMapOutlinesFrame";
// Wraps a method of the game's map class; stop() puts the original back on the class.
function wrap(proto, name) {
    const original = proto[name];
    if (typeof original !== "function")
        throw new Error("this game build has no " + name);
    const wrapper = function (...args) {
        const result = original.apply(this, args);
        const frame = globalThis[FRAME_KEY];
        if (typeof frame === "function")
            frame(this);
        return result;
    };
    proto[name] = wrapper;
    wrapped.push({ proto, name, original, wrapper });
}
// This copy's part of a world map frame (globalThis[FRAME_KEY] while it runs).
function onFrame(host) {
    if (run.stopped || !host.BigMapMode)
        return; // the game's own method does nothing outside the world map either
    try {
        update(host);
    }
    catch (e) {
        warnOnce(`world map: ${e}`);
    }
}
try {
    if (!puerts.argv.getByName("GameInstance"))
        throw new Error("the GameInstance is missing");
    const missing = REGIONS.filter((r) => !IMAGES[r.id]).map((r) => r.id);
    if (missing.length)
        throw new Error("no image for " + missing.join(", "));
    const MapInterface = require("UI/Widget/Map").MapInterface;
    if (!MapInterface || !MapInterface.prototype)
        throw new Error("UI/Widget/Map has no MapInterface");
    wrap(MapInterface.prototype, "UpdateBigMapGadgetIcon");
    globalThis[FRAME_KEY] = onFrame;
    run.path = settingsPath();
    console.log(`[PBZMOD] [${MOD_NAME}] ${MOD_VERSION} started; settings: ${run.path}` + (menu.on ? " (Mods Menu's page)" : ""));
}
catch (e) {
    run.stopped = true;
    console.warn(`[${MOD_NAME}] not started: ${e}`);
    throw e;
}

exports.stop = function () {
    run.stopped = true;
    if (globalThis[FRAME_KEY] === onFrame)
        delete globalThis[FRAME_KEY];
    for (const host of [...hosts]) {
        try {
            removeOutlines(host);
        }
        catch (e) {
            console.warn(`[${MOD_NAME}] stop: ${e}`);
        }
    }
    for (const w of wrapped.splice(0))
        if (w.proto[w.name] === w.wrapper)
            w.proto[w.name] = w.original;
    console.log(`[PBZMOD] [${MOD_NAME}] stopped`);
};
